import time

import numpy as np
import torch
import torch.nn as nn

torch.manual_seed(0)
X = torch.randn(364, 13)
y = torch.randn(364, 1)


def build():
    m = nn.Sequential()
    m.add_module('d1', nn.Dropout(0.005))
    m.add_module('f1', nn.Linear(13, 50))
    m.add_module('f2', nn.Lropout() if False else nn.Linear(50, 1))
    return m


class Net(nn.Module):
    def __init__(self, p):
        super().__init__()
        self.d1 = nn.Dropout(p)
        self.f1 = nn.Linear(13, 50)
        self.d2 = nn.Dropout(p)
        self.f2 = nn.Linear(50, 1)

    def forward(self, x):
        return self.f2(self.d2(torch.relu(self.f1(self.d1(x)))))

    def l2(self):
        return self.f1.weight.pow(2).sum() + self.f2.weight.pow(2).sum()


def bench(threads, opt_name, bs, epochs=400, reg=1e-6):
    torch.set_num_threads(threads)
    m = Net(0.005)
    if opt_name == 'adam':
        opt = torch.optim.Adam(m.parameters(), lr=1e-3)
    else:
        opt = torch.optim.SGD(m.parameters(), lr=1e-3)
    n = X.shape[0]
    t = time.time()
    for _ in range(epochs):
        order = torch.randperm(n)
        for s in range(0, n, bs):
            idx = order[s:s + bs]
            opt.zero_grad()
            loss = torch.mean((m(X[idx]) - y[idx]) ** 2) + reg * m.l2()
            loss.backward()
            opt.step()
    return time.time() - t


for threads in [1, 7]:
    for opt_name in ['adam', 'sgd']:
        for bs in [32, 128]:
            print('threads=%d %-5s bs=%3d : %.2fs' % (threads, opt_name, bs,
                                                      bench(threads, opt_name, bs)))
